<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import QRCode from 'qrcode'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,initialUser?:string}>()
const emit=defineEmits<{policies:[]}>()
const users=ref<Row[]>([]),profiles=ref<Row[]>([]),shares=ref<Row[]>([]),services=ref<Row[]>([]),editing=ref<Row|null>(null),removing=ref<Row|null>(null),error=ref(''),notice=ref(''),busy=ref(false),url=ref(''),format=ref('auto'),diagnostic=ref<Row|null>(null),diagnosticID=ref('')
const site=ref<Row>({}),linkOrigin=ref('preferred')
const managementOrigin=computed(()=>site.value.domain?(site.value.https?'https://':'http://')+site.value.domain:site.value.ip_origin||'')
const backupURL=computed(()=>{try{if(!url.value||!managementOrigin.value)return '';const u=new URL(url.value),m=new URL(managementOrigin.value);if(u.origin===m.origin)return '';return m.origin+u.pathname}catch{return ''}})
const selectedURL=computed(()=>linkOrigin.value==='management'&&backupURL.value?backupURL.value:url.value)
const advanced=ref(false),legacySingBox=ref(false),qr=ref(''),qrSingBox=ref(''),qrMode=ref('subscription'),qrNodes=ref<Row[]>([]),qrNode=ref('')
async function showQR(){qr.value='';qrSingBox.value='';await check();if(!readiness.value?.ready)return;try{let payload=formatted.value;if(format.value==='sing-box'||format.value==='sing-box-latest')payload='sing-box://import-remote-profile?url='+encodeURIComponent(formatted.value)+'#Starhub';if(qrMode.value==='node'){qrNodes.value=await props.api('subscriptions/'+shareID.value+'/nodes');const node=qrNodes.value.find(n=>n.id===qrNode.value)||qrNodes.value[0];if(!node)throw Error('没有可生成 URI 的兼容节点');qrNode.value=node.id;payload=node.uri};qr.value=await QRCode.toDataURL(payload,{width:320,margin:3,errorCorrectionLevel:'M'});if(format.value==='auto'&&qrMode.value==='subscription'){const singUrl=selectedURL.value+'?client=sing-box-latest';qrSingBox.value=await QRCode.toDataURL('sing-box://import-remote-profile?url='+encodeURIComponent(singUrl)+'#Starhub',{width:320,margin:3,errorCorrectionLevel:'M'})}}catch(e){error.value=String(e)}}
watch([qrMode,qrNode],()=>{qr.value='';qrSingBox.value=''})
const primaryFormats=[{id:'mihomo',name:'Clash / Mihomo · Clash Verge、FlClash、Stash'},{id:'shadowrocket',name:'Shadowrocket 小火箭 · 节点订阅'},{id:'hiddify',name:'Hiddify · App 配置（过滤未适配协议）'},{id:'sing-box-latest',name:'sing-box · Android / iOS / 1.14+'},{id:'v2rayng',name:'v2rayNG · 可选节点订阅'},{id:'v2rayn',name:'v2rayN · 可选节点订阅'},{id:'nekobox',name:'NekoBox Android · Clash Meta 节点 YAML'},{id:'happ',name:'Happ · 节点订阅'},{id:'v2raytun',name:'v2RayTun · 节点订阅'}]
const availableFormats=computed(()=>advanced.value?formats.value:primaryFormats)
const shareID=ref(''),readiness=ref<Row|null>(null),checking=ref(false)
let checkSequence=0
const fallbackFormats=[{id:'sing-box',name:'sing-box JSON'},{id:'mihomo',name:'Mihomo'},{id:'shadowrocket',name:'Shadowrocket URI'},{id:'xray',name:'Xray JSON'}]
const formats=ref(fallbackFormats), catalog=ref<Row[]>([])
const activeFormat=computed(()=>format.value==='sing-box-latest'&&legacySingBox.value?'sing-box':format.value)
const formatted=computed(()=>selectedURL.value?selectedURL.value+(activeFormat.value==='auto'?'':'?client='+activeFormat.value+(['shadowrocket','base64','v2rayng','v2rayn','v2rayng-uri','nekobox','nekobox-uri','happ','v2raytun','naive-proxy'].includes(activeFormat.value)?'&policy=nodes-only':'')):'')
async function reload(){try{catalog.value=await props.api('client-catalog');if(catalog.value.length)formats.value=catalog.value.filter(c=>!['sing-box','sfa'].includes(c.id)).map(c=>({id:c.id,name:c.name+(c.id==='shadowrocket-config'?' · 分流规则':c.full_config?' · 完整策略':' · 仅节点')}))}catch{};[users.value,profiles.value,shares.value,services.value]=await Promise.all(['proxy-users','client-profiles','subscriptions','live'].map(p=>props.api(p)));try{site.value=await props.api('site')}catch{site.value={}}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
function create(){editing.value={name:'',user_id:props.initialUser||users.value.find(u=>u.active)?.id||'',profile_id:'',days:30,service_ids:[],mode:'user'}}
async function openUserShare(user:string){if(!user)return;const r=await props.api('proxy-users/'+user+'/subscription','POST',{});url.value=r.url;shareID.value=r.id;format.value='auto';editing.value=null;notice.value=r.reused?'已打开用户原订阅链接，无须重新创建。':'已生成用户订阅链接。';await reload()}
onMounted(()=>void run(async()=>{await reload();if(props.initialUser)await openUserShare(props.initialUser)}))
watch(()=>props.initialUser,id=>{if(id)void run(()=>openUserShare(id))})
onUnmounted(()=>url.value='')
function edit(row:Row){editing.value={...JSON.parse(JSON.stringify(row)),original_user_id:row.user_id??'',original_service_ids:row.service_ids??[],original_expires_at:row.expires_at,expires_at:row.expires_at?.slice(0,10),mode:row.user_id?'user':'shared',service_ids:row.service_ids??[]}}
function save(){const v=editing.value;if(!v)return;void run(async()=>{if(v.id){const user=v.mode==='user'?v.user_id:'';const services=v.mode==='shared'?v.service_ids:[];const changed=!v.device_id&&(user!==v.original_user_id||JSON.stringify([...services].sort())!==JSON.stringify([...v.original_service_ids].sort()));await props.api('subscriptions/'+v.id,'PUT',{name:v.name,profile_id:v.profile_id??'',expires_at:v.expires_at===v.original_expires_at?.slice(0,10)?v.original_expires_at:new Date(v.expires_at+'T23:59:59').toISOString(),version:v.version,...(changed?{user_id:user,service_ids:services}:{})})}else{const r=await props.api('subscriptions','POST',{name:v.name,user_id:v.mode==='user'?v.user_id:'',service_ids:v.mode==='shared'?v.service_ids:[],profile_id:v.profile_id,days:v.days});url.value=r.url;shareID.value=r.id;format.value='auto'};editing.value=null;notice.value='已保存';await reload()})}
function link(r:Row,rotate=false){void run(async()=>{const result=await props.api('subscriptions/'+r.id+(rotate?'/rotate':'/link'),rotate?'POST':'GET',rotate?{}:undefined);url.value=result.url;shareID.value=r.id;format.value='auto'})}
async function copy(){await check();if(!readiness.value?.ready){error.value=readiness.value?.reason??'请先通过订阅检查';return};try{await navigator.clipboard.writeText(formatted.value);notice.value='已复制所选客户端格式的链接'}catch{error.value='请选中下方链接手动复制'}}
async function check(){if(!url.value||!shareID.value)return;const seq=++checkSequence;checking.value=true;readiness.value=null;try{const query=activeFormat.value==='auto'?'':('?client='+activeFormat.value+(['shadowrocket','base64','v2rayng','v2rayn','v2rayng-uri','nekobox','nekobox-uri','happ','v2raytun','naive-proxy'].includes(activeFormat.value)?'&policy=nodes-only':''));const result=await props.api('subscriptions/'+shareID.value+'/check'+query);if(seq===checkSequence)readiness.value=result}catch{if(seq===checkSequence)readiness.value={ready:false,reason:'检查请求失败，请确认控制端连接后重试'}}finally{if(seq===checkSequence)checking.value=false}}
watch([url,format,legacySingBox,linkOrigin],()=>{qr.value='';qrSingBox.value='';qrNodes.value=[];qrNode.value='';if(url.value)void check();else{checkSequence++;readiness.value=null;checking.value=false}})
function remove(){const r=removing.value;if(!r)return;void run(async()=>{await props.api('subscriptions'+'/'+r.id,'DELETE');removing.value=null;url.value='';await reload()})}
function migrate(row:Row){if(!window.confirm('迁移后该订阅使用独立身份，客户端需要更新订阅；不支持独立身份的共享密钥入口会被过滤。其他旧订阅存在时，其旧身份仍有效。继续？'))return;void run(async()=>{const result=await props.api('subscriptions/'+row.id+'/independent-identity','POST',{});notice.value=result.legacy_identity_still_active?'已迁移；请更新客户端，其他旧订阅仍使用旧身份。':'已迁移；等待主机同步后更新客户端。';await reload()})}
function inspect(id:string){diagnosticID.value=id;void run(async()=>{diagnostic.value=await props.api('subscriptions/'+id+'/usage')})}
function inspectConfig(){void run(async()=>{diagnostic.value=await props.api('subscriptions/'+diagnosticID.value+'/config'+(activeFormat.value==='auto'?'':'?client='+activeFormat.value+(['shadowrocket','base64','v2rayng','v2rayn','v2rayng-uri','nekobox','nekobox-uri','happ','v2raytun','naive-proxy'].includes(activeFormat.value)?'&policy=nodes-only':'')))})}
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><h2>客户端订阅</h2><p class="muted">选择用户即可分享其获授权节点及客户端策略，格式可手动切换。IPv4 使用原名，IPv6 使用原名-v6。</p></div><div class="row-actions"><button class="secondary" @click="advanced=!advanced">{{advanced?'收起高级选项':'高级选项'}}</button><button v-if="advanced" class="primary" @click="create">＋ 额外订阅</button></div></div><p class="form-note">基础配置、DNS、策略组和规则统一在客户端策略中编辑；此页管理用户、链接有效期和分享链接。独立身份订阅到期会在主机同步后撤销其身份；旧订阅到期仅停止下载，可手动迁移。用户到期也会撤销其托管身份。用户组增加节点后，原链接在 Agent 应用完成后提供最新全量配置；客户端需执行更新订阅，无须重建用户。<button class="text-button" @click="emit('policies')">前往客户端策略</button></p><p class="form-note">兼容模式支持 Clash Verge / FlClash，按来源地址和客户端识别订阅访问名额；严格 HWID 模式仅限支持自报标识的客户端。记录不等于物理设备证明，也不能阻止复制已下载的凭据。管理员检查不消耗名额。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
<label>选择用户打开原订阅链接<select aria-label="选择分享用户" :value="initialUser||''" @change="run(()=>openUserShare(($event.target as HTMLSelectElement).value))"><option value="">选择已有用户</option><option v-for="u in users.filter(u=>u.active)" :key="u.id" :value="u.id">{{u.name}}</option></select></label>
<div v-if="url" class="share-box"><p>订阅名称：{{shares.find(s=>s.id===shareID)?.name||'加载中'}} <button v-if="shares.find(s=>s.id===shareID)" class="text-button" @click="edit(shares.find(s=>s.id===shareID)!)">修改名称</button></p><div class="fields"><label v-if="backupURL">订阅入口<select v-model="linkOrigin" aria-label="订阅入口"><option value="preferred">独立订阅域名（默认）</option><option value="management">后台域名 / IP 备用入口</option></select></label><label>客户端格式<select v-model="format" aria-label="客户端格式"><option value="auto">自动识别客户端（推荐）</option><option v-for="f in availableFormats" :key="f.id" :value="f.id">{{f.name}}</option></select></label><label v-if="format==='sing-box-latest'" class="check-label"><input v-model="legacySingBox" type="checkbox">兼容 sing-box 1.12–1.13（旧版格式，不含 Snell）</label><label>订阅链接<input :value="formatted" readonly @focus="($event.target as HTMLInputElement).select()"></label></div><template v-if="format==='shadowrocket-config'"><p class="notice">小火箭分两步导入：下方为分流配置，节点使用此配套订阅。分流目标 PROXY 跟随应用当前选中的代理。</p><label>配套节点订阅<input :value="selectedURL+'?client=shadowrocket&amp;policy=nodes-only'" readonly @focus="($event.target as HTMLInputElement).select()"></label></template><p v-if="checking" class="muted" role="status">正在生成并检查所选客户端订阅…</p><p v-else-if="readiness" :class="readiness.ready?'notice':'error'" role="status">{{readiness.ready?'✓ 配置检查通过：':'暂不可分享：'}}{{readiness.reason}}<span v-if="readiness.excluded_nodes&&readiness.excluded_nodes!=='0'"> · 已过滤 {{readiness.excluded_nodes}} 个不兼容入口</span></p><button class="secondary" :disabled="checking" @click="check">重新检查</button><button class="primary" :disabled="checking||!readiness?.ready" @click="copy">复制订阅链接</button><label>二维码类型<select v-model="qrMode" aria-label="二维码类型"><option value="subscription">订阅链接</option><option value="node">单节点 URI · 兼容旧版 NekoBox</option></select></label><label v-if="qrMode==='node'&&qrNodes.length">单节点<select v-model="qrNode" aria-label="二维码节点"><option v-for="n in qrNodes" :key="n.id" :value="n.id">{{n.name}}</option></select></label><button class="secondary" :disabled="checking||!readiness?.ready" @click="showQR">生成二维码</button><button class="text-button" @click="url=''">收起链接</button><div v-if="qr" class="share-qr"><p v-if="qrSingBox">通用客户端订阅二维码</p><img :src="qr" alt="当前所选客户端的私密订阅链接二维码" width="260" height="260"><template v-if="qrSingBox"><p>sing-box 专用二维码（同一用户订阅）</p><img :src="qrSingBox" alt="sing-box 远程配置二维码" width="260" height="260"></template><p class="muted">二维码包含私密凭据，请勿公开。自动模式提供通用与 sing-box 专用二维码；NekoBox 1.4 以前请用单节点 URI 扫码，单节点不自动更新。</p></div><p class="muted">完整配置自动带入用户与客户端策略；仅节点格式无法携带规则。自动识别和手动选择均筛选兼容节点。共享密钥流量无法可靠归属个人；SS 2022 / Snell 可在节点中显式启用独立用户身份计量。</p></div>
<div class="table-scroll"><table><thead><tr><th>订阅</th><th>所属用户 / 输出预设</th><th>链接有效期</th><th>操作</th></tr></thead><tbody><tr v-for="s in shares" :key="s.id"><td>{{s.name}}<small class="block-muted">{{s.independent_identity?'独立身份':'旧版 / 共享身份'}}</small><small class="block-muted">{{s.revoked_at?'已撤销':s.active===false?'已到期':'有效'}}</small></td><td>{{users.find(u=>u.id===s.user_id)?.name??'共享密钥订阅'}}<small class="block-muted">{{profiles.find(p=>p.id===s.profile_id)?.name??'跟随客户端策略'}}</small></td><td>{{new Date(s.expires_at).toLocaleDateString()}}</td><td class="row-actions"><button class="text-button" :disabled="!!s.revoked_at" @click="link(s)">分享链接</button><button class="text-button" :disabled="!!s.revoked_at" @click="inspect(s.id)">用量 / 客户端配置</button><button v-if="s.user_id&&!s.independent_identity&&!s.revoked_at" class="text-button" @click="migrate(s)">迁移独立身份</button><button class="text-button" :disabled="!!s.revoked_at" @click="edit(s)">编辑</button><button class="text-button" :disabled="!!s.revoked_at" @click="removing={...s,rotate:true}">重置链接</button><button class="text-button danger" @click="removing=s">删除</button></td></tr></tbody></table></div><p v-if="!shares.length" class="console-empty">选择已有用户，或在用户权限页面点击分享订阅。</p></section>
<div v-if="editing" class="modal-backdrop" @keydown.esc="editing=null"><form class="modal" role="dialog" aria-modal="true" aria-label="订阅配置" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'编辑':'添加'}}订阅</h2><button type="button" class="secondary" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" class="error" role="alert">{{error}}</p><div class="fields"><label>名称<input v-model="editing.name" required maxlength="100"></label><template><label >授权方式<select v-model="editing.mode" :disabled="!!editing.device_id"><option value="user">用户权限（推荐）</option><option value="shared">共享密钥配置（SS / Snell 等）</option></select></label><label v-if="editing.mode==='user'">所属用户<select v-model="editing.user_id" :disabled="!!editing.device_id" required><option value="">选择已分配权限的用户</option><option v-for="u in users.filter(u=>u.enabled!==false&&new Date(u.expires_at)>new Date())" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>高级：订阅输出预设（可选）<select v-model="editing.profile_id"><option value="">跟随客户端策略（推荐）</option><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}} · {{p.format}}</option></select></label><label v-if="editing.id">链接有效期至<input v-model="editing.expires_at" type="date" required></label><label v-else>有效天数<input v-model.number="editing.days" type="number" min="1" max="365" required></label></template></div><div v-if="editing.mode==='shared'" class="choice-list"><label v-for="s in services.filter(s=>!s.managed_users&&!s.delete_requested_at&&!['frpc','frps'].includes(s.kind))" :key="s.id"><input v-model="editing.service_ids" type="checkbox" :value="s.id">{{s.name}} · {{s.kind}}</label><p class="muted">共享密钥无法单独撤销某一用户；需要轮换协议密钥。</p></div><p v-if="editing.id" class="form-note">修改绑定用户后，客户端需要更新订阅；旧共享密钥的撤销仍需轮换节点凭据。</p><p class="muted">用户订阅会随用户组权限变化；停用、离线或尚未应用的入站不会发布。独立身份订阅到期后主机同步撤销其独立凭据；旧订阅需要手动迁移。共享密钥无法单独撤销用户，会从独立身份订阅中排除。</p></div><div class="modal-footer"><button class="secondary" type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存</button></div></form></div>
<div v-if="diagnostic" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="订阅用量诊断"><div class="modal-heading"><h2>订阅用量与客户端配置</h2><button class="secondary" @click="diagnostic=null">关闭</button></div><div class="form-content"><p>{{diagnostic.notice}}</p><p class="form-note">Clash 用量卡片在更新订阅时读取响应头；共享订阅没有个人额度。0 B 也可能是此身份尚未产生流量。</p><label>预览客户端格式<select v-model="format" aria-label="客户端格式"><option value="auto">自动 / 模板默认</option><option v-for="f in availableFormats" :key="f.id" :value="f.id">{{f.name}}</option></select></label><button class="secondary" :disabled="busy" @click="inspectConfig">查看生成配置与响应头</button><p v-if="error" class="error">{{error}}</p><pre class="native-preview">{{JSON.stringify(diagnostic,null,2)}}</pre><p class="muted">凭据已隐藏。客户端配置在“客户端策略”修改；关联的历史输出预设最后覆盖，VPS 入站在节点配置中修改。</p></div></section></div><div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="确认订阅操作"><div class="form-content"><h2>{{removing.rotate?'重置链接':'删除'}} {{removing.name}}？</h2><p>{{removing.rotate?'旧链接将立即失效，需要重新分发。':'立即停止此链接下载。已导入的代理凭据仍有效，撤销访问请停用用户或轮换凭据。'}}</p><p v-if="error" class="error" role="alert">{{error}}</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="primary" :disabled="busy" @click="removing.rotate?(link(removing,true),removing=null):remove()">确认</button></div></section></div></template>

<style scoped>.share-qr{display:grid;justify-items:center;gap:12px;padding:20px;max-width:400px}.share-qr img{background:white;border-radius:12px;max-width:100%;height:auto}</style>
